"use client"
import { useState, useEffect, useRef } from 'react'
import Link from 'next/link'
import { usePathname, useRouter } from 'next/navigation'
import { PUBLISHERS, type Publisher } from '../data/books'

const CATEGORIES = [
  { label: 'Publication', key: 'publication' },
  { label: 'Award',       key: 'award'       },
  { label: 'Best Seller', key: 'best-seller' },
  { label: 'Recent',      key: 'recent'      },
] as const

const PUB_KEYS = Object.keys(PUBLISHERS) as Publisher[]

export default function Header() {
  const [scrolled,   setScrolled  ] = useState(false)
  const [menuOpen,   setMenuOpen  ] = useState(false)
  const [megaOpen,   setMegaOpen  ] = useState(false)
  const [pubHover,   setPubHover  ] = useState(false)
  const [mobileBooks,setMobileBooks] = useState(false)
  const [mobilePub,  setMobilePub ] = useState(false)
  const megaTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const pathname = usePathname()
  const router = useRouter()

  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 60)
    window.addEventListener('scroll', fn, { passive: true })
    return () => window.removeEventListener('scroll', fn)
  }, [])

  useEffect(() => {
    document.body.style.overflow = menuOpen ? 'hidden' : ''
    return () => { document.body.style.overflow = '' }
  }, [menuOpen])

  useEffect(() => {
    setMenuOpen(false)
    setMegaOpen(false)
    setMobileBooks(false)
    setMobilePub(false)
  }, [pathname])

  const openMega  = () => { if (megaTimer.current) clearTimeout(megaTimer.current); setMegaOpen(true) }
  const closeMega = () => { megaTimer.current = setTimeout(() => setMegaOpen(false), 160) }

  const go = (href: string) => {
    setMenuOpen(false)
    if (href.startsWith('#')) {
      if (pathname !== '/') { router.push('/'); setTimeout(() => document.querySelector(href)?.scrollIntoView({ behavior: 'smooth' }), 400) }
      else document.querySelector(href)?.scrollIntoView({ behavior: 'smooth' })
    }
  }

  const navLinkStyle = (active = false): React.CSSProperties => ({
    fontFamily: 'Inter, sans-serif',
    fontSize: '0.6875rem',
    fontWeight: 400,
    letterSpacing: '0.16em',
    textTransform: 'uppercase',
    color: active ? '#0e0c0a' : 'rgba(14,12,10,0.42)',
    textDecoration: 'none',
    transition: 'color 0.25s',
    cursor: 'none',
    background: 'none',
    border: 'none',
    padding: 0,
  })

  const isBooksActive = pathname.startsWith('/books')
  const isAdvActive   = pathname.startsWith('/advertisement')

  return (
    <>
      <header style={{
        position: 'fixed', top: 0, left: 0, right: 0, zIndex: 600,
        transition: 'background 0.5s, border-color 0.5s',
        background: scrolled || megaOpen ? 'rgba(244,241,234,0.96)' : 'transparent',
        backdropFilter: scrolled || megaOpen ? 'blur(20px)' : 'none',
        WebkitBackdropFilter: scrolled || megaOpen ? 'blur(20px)' : 'none',
        borderBottom: scrolled || megaOpen ? '1px solid rgba(14,12,10,0.08)' : '1px solid transparent',
      }}>
        <div style={{
          maxWidth: 1280, margin: '0 auto',
          padding: '0 clamp(1.5rem, 5.5vw, 5rem)',
          height: 68,
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        }}>

          {/* ── Left cluster: logo + Books + Advertisement ── */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 'clamp(1.5rem, 3vw, 2.5rem)' }}>
            <Link href="/" data-hover="true" style={{
              fontFamily: "'Fraunces', serif",
              fontSize: '1rem', fontWeight: 300, letterSpacing: '0.015em',
              color: '#0e0c0a', textDecoration: 'none', transition: 'color 0.3s',
            }}
              onMouseEnter={e => (e.currentTarget.style.color = '#c9a227')}
              onMouseLeave={e => (e.currentTarget.style.color = '#0e0c0a')}>
              Sachin Yagol
            </Link>

            {/* Desktop: Books trigger */}
            <div
              className="hdr-nav"
              style={{ display: 'none', position: 'relative' }}
              onMouseEnter={openMega}
              onMouseLeave={closeMega}
            >
              <button data-hover="true"
                style={{ ...navLinkStyle(isBooksActive), display: 'flex', alignItems: 'center', gap: '0.35rem' }}
                onMouseEnter={e => (e.currentTarget.style.color = '#0e0c0a')}
                onMouseLeave={e => (e.currentTarget.style.color = isBooksActive ? '#0e0c0a' : 'rgba(14,12,10,0.42)')}
                onClick={() => router.push('/books')}
                aria-expanded={megaOpen}
                aria-haspopup="true">
                Books
                <svg width="8" height="5" viewBox="0 0 8 5" fill="none"
                  style={{ transition: 'transform 0.25s', transform: megaOpen ? 'rotate(180deg)' : 'none', opacity: 0.5 }}>
                  <path d="M1 1l3 3 3-3" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </button>

              {/* ── Mega-menu panel ── */}
              <div
                onMouseEnter={openMega}
                onMouseLeave={closeMega}
                style={{
                  position: 'fixed', top: 68, left: 0, right: 0,
                  background: 'rgba(244,241,234,0.98)',
                  backdropFilter: 'blur(20px)',
                  WebkitBackdropFilter: 'blur(20px)',
                  borderBottom: '1px solid rgba(14,12,10,0.08)',
                  zIndex: 590,
                  pointerEvents: megaOpen ? 'auto' : 'none',
                  opacity: megaOpen ? 1 : 0,
                  transform: megaOpen ? 'translateY(0)' : 'translateY(-8px)',
                  transition: 'opacity 0.25s, transform 0.25s',
                }}>
                <div style={{ maxWidth: 1280, margin: '0 auto', padding: '2.5rem clamp(1.5rem, 5.5vw, 5rem) 2.5rem' }}>

                  {/* Publication row */}
                  <div style={{ marginBottom: '2rem' }}
                    onMouseEnter={() => setPubHover(true)}
                    onMouseLeave={() => setPubHover(false)}>
                    <span style={{
                      display: 'block',
                      fontFamily: 'Inter, sans-serif', fontSize: '0.5625rem', fontWeight: 500,
                      letterSpacing: '0.22em', textTransform: 'uppercase',
                      color: '#c9a227', marginBottom: '1rem',
                    }}>Publication</span>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                      {PUB_KEYS.map(p => (
                        <button key={p} onClick={() => router.push(`/books/publication/${p}`)} data-hover="true"
                          style={{
                            fontFamily: 'Inter, sans-serif', fontSize: '0.75rem',
                            fontWeight: 400, letterSpacing: '0.06em',
                            color: 'rgba(14,12,10,0.55)',
                            padding: '0.4em 0.9em',
                            border: '1px solid rgba(14,12,10,0.12)',
                            background: 'transparent',
                            transition: 'background 0.2s, color 0.2s, border-color 0.2s',
                            textDecoration: 'none',
                          }}
                          onMouseEnter={e => {
                            e.currentTarget.style.background = '#0e0c0a'
                            e.currentTarget.style.color = '#f4f1ea'
                            e.currentTarget.style.borderColor = '#0e0c0a'
                          }}
                          onMouseLeave={e => {
                            e.currentTarget.style.background = 'transparent'
                            e.currentTarget.style.color = 'rgba(14,12,10,0.55)'
                            e.currentTarget.style.borderColor = 'rgba(14,12,10,0.12)'
                          }}>
                          {PUBLISHERS[p].short ? `${PUBLISHERS[p].label} [${PUBLISHERS[p].short}]` : PUBLISHERS[p].label}
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Divider */}
                  <div style={{ height: 1, background: 'rgba(14,12,10,0.07)', marginBottom: '1.75rem' }} />

                  {/* Category row */}
                  <div style={{ display: 'flex', gap: '3rem', flexWrap: 'wrap' }}>
                    {CATEGORIES.slice(1).map(c => (
                      <Link key={c.key} href={`/books/${c.key}`} data-hover="true"
                        style={{
                          fontFamily: "'Fraunces', serif",
                          fontSize: 'clamp(1.375rem, 2.5vw, 1.875rem)',
                          fontWeight: 200, letterSpacing: '-0.02em',
                          color: 'rgba(14,12,10,0.35)',
                          transition: 'color 0.25s',
                          textDecoration: 'none',
                        }}
                        onMouseEnter={e => (e.currentTarget.style.color = '#0e0c0a')}
                        onMouseLeave={e => (e.currentTarget.style.color = 'rgba(14,12,10,0.35)')}>
                        {c.label}
                      </Link>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Desktop: Advertisement */}
            <Link href="/advertisement" className="hdr-nav" data-hover="true"
              style={{ ...navLinkStyle(isAdvActive), display: 'none' }}
              onMouseEnter={e => (e.currentTarget.style.color = '#0e0c0a')}
              onMouseLeave={e => (e.currentTarget.style.color = isAdvActive ? '#0e0c0a' : 'rgba(14,12,10,0.42)')}>
              Advertisement
            </Link>
          </div>

          {/* ── Right cluster: About + Contact ── */}
          <nav className="hdr-nav" style={{ display: 'none' }}>
            <ul style={{ display: 'flex', gap: '2rem', margin: 0 }}>
              {[{ label: 'About', href: '#about' }, { label: 'Contact', href: '#contact' }].map(l => (
                <li key={l.label}>
                  <a href={l.href} data-hover="true"
                    onClick={e => { e.preventDefault(); go(l.href) }}
                    style={navLinkStyle()}
                    onMouseEnter={e => (e.currentTarget.style.color = '#0e0c0a')}
                    onMouseLeave={e => (e.currentTarget.style.color = 'rgba(14,12,10,0.42)')}>
                    {l.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          {/* ── Hamburger ── */}
          <button className="hdr-burger" data-hover="true"
            onClick={() => setMenuOpen(o => !o)}
            aria-label={menuOpen ? 'Close' : 'Menu'}
            aria-expanded={menuOpen}
            style={{ display: 'flex', flexDirection: 'column', gap: 5, padding: 8, background: 'none', border: 'none', color: '#0e0c0a' }}>
            <span style={{ display: 'block', width: 22, height: 1, background: 'currentColor', transition: 'transform 0.35s', transform: menuOpen ? 'translateY(3px) rotate(45deg)' : 'none' }} />
            <span style={{ display: 'block', width: 22, height: 1, background: 'currentColor', transition: 'transform 0.35s', transform: menuOpen ? 'translateY(-3px) rotate(-45deg)' : 'none' }} />
          </button>
        </div>
      </header>

      {/* ── Mobile overlay ── */}
      <div style={{
        position: 'fixed', inset: 0, zIndex: 500,
        background: '#f4f1ea',
        display: 'flex', flexDirection: 'column',
        overflowY: 'auto',
        opacity: menuOpen ? 1 : 0,
        pointerEvents: menuOpen ? 'auto' : 'none',
        transition: 'opacity 0.4s cubic-bezier(0.16,1,0.3,1)',
        padding: '100px clamp(1.5rem,7vw,4rem) 3rem',
      }}>
        <ul style={{ margin: 0, display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>

          {/* Books accordion */}
          <li>
            <button data-hover="true"
              onClick={() => setMobileBooks(o => !o)}
              style={{
                fontFamily: "'Fraunces', serif", fontSize: 'clamp(2.25rem,9vw,3.5rem)',
                fontWeight: 200, letterSpacing: '-0.03em',
                color: mobileBooks ? '#0e0c0a' : 'rgba(14,12,10,0.38)',
                background: 'none', border: 'none', padding: '0.25rem 0',
                display: 'flex', alignItems: 'center', gap: '0.75rem',
                transition: 'color 0.25s', width: '100%', textAlign: 'left',
              }}>
              Books
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"
                style={{ transition: 'transform 0.3s', transform: mobileBooks ? 'rotate(180deg)' : 'none', opacity: 0.4 }}>
                <path d="M1 1l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>

            {mobileBooks && (
              <ul style={{ margin: '0.5rem 0 1rem 1.5rem', display: 'flex', flexDirection: 'column', gap: '0.1rem' }}>
                {/* Publication sub-accordion */}
                <li>
                  <button data-hover="true"
                    onClick={() => setMobilePub(o => !o)}
                    style={{
                      fontFamily: 'Inter, sans-serif', fontSize: '0.7rem', fontWeight: 500,
                      letterSpacing: '0.18em', textTransform: 'uppercase',
                      color: '#c9a227', background: 'none', border: 'none', padding: '0.5rem 0',
                      display: 'flex', alignItems: 'center', gap: '0.4rem',
                    }}>
                    Publication
                    <svg width="8" height="5" viewBox="0 0 8 5" fill="none"
                      style={{ transition: 'transform 0.3s', transform: mobilePub ? 'rotate(180deg)' : 'none', opacity: 0.6 }}>
                      <path d="M1 1l3 3 3-3" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                  </button>
                  {mobilePub && (
                    <ul style={{ margin: '0.25rem 0 0.75rem 1rem', display: 'flex', flexDirection: 'column', gap: '0' }}>
                      {PUB_KEYS.map(p => (
                        <li key={p}>
                          <Link href={`/books/publication/${p}`} data-hover="true"
                            style={{ fontFamily: 'Inter, sans-serif', fontSize: '0.8125rem', color: 'rgba(14,12,10,0.55)', letterSpacing: '0.04em', display: 'block', padding: '0.4rem 0' }}>
                            {PUBLISHERS[p].label} {PUBLISHERS[p].short ? `[${PUBLISHERS[p].short}]` : ''}
                          </Link>
                        </li>
                      ))}
                    </ul>
                  )}
                </li>
                {CATEGORIES.slice(1).map(c => (
                  <li key={c.key}>
                    <Link href={`/books/${c.key}`} data-hover="true"
                      style={{ fontFamily: 'Inter, sans-serif', fontSize: '0.7rem', fontWeight: 500, letterSpacing: '0.18em', textTransform: 'uppercase', color: 'rgba(14,12,10,0.50)', display: 'block', padding: '0.5rem 0' }}>
                      {c.label}
                    </Link>
                  </li>
                ))}
              </ul>
            )}
          </li>

          <li>
            <Link href="/advertisement" data-hover="true"
              style={{ fontFamily: "'Fraunces', serif", fontSize: 'clamp(2.25rem,9vw,3.5rem)', fontWeight: 200, letterSpacing: '-0.03em', color: 'rgba(14,12,10,0.38)', display: 'block', padding: '0.25rem 0' }}>
              Advertisement
            </Link>
          </li>

          <li style={{ marginTop: '1.5rem', paddingTop: '1.5rem', borderTop: '1px solid rgba(14,12,10,0.08)' }}>
            <a href="#about" data-hover="true"
              onClick={e => { e.preventDefault(); go('#about') }}
              style={{ fontFamily: 'Inter, sans-serif', fontSize: '0.7rem', fontWeight: 500, letterSpacing: '0.18em', textTransform: 'uppercase', color: 'rgba(14,12,10,0.40)', display: 'block', padding: '0.5rem 0' }}>
              About
            </a>
          </li>
          <li>
            <a href="#contact" data-hover="true"
              onClick={e => { e.preventDefault(); go('#contact') }}
              style={{ fontFamily: 'Inter, sans-serif', fontSize: '0.7rem', fontWeight: 500, letterSpacing: '0.18em', textTransform: 'uppercase', color: 'rgba(14,12,10,0.40)', display: 'block', padding: '0.5rem 0' }}>
              Contact
            </a>
          </li>
        </ul>
      </div>

      <style>{`
        @media (min-width: 768px) {
          .hdr-nav    { display: flex !important; }
          .hdr-burger { display: none !important; }
        }
      `}</style>
    </>
  )
}
