export type Publisher = 'fp' | 'bh' | 'nepalaya' | 'kitab' | 'sunbarshi' | 'kalam' | 'lipi' | 'indigo' | 'other'
export type BookTag = 'award' | 'best-seller' | 'recent'

export type Book = {
  id: string
  title: string
  author: string
  publisher: Publisher
  tags: BookTag[]
  year: number
  /* visual tokens used to render the typographic cover card */
  palette: { bg: string; text: string; accent: string }
  layout: 'top-left' | 'center' | 'bottom-left' | 'bottom-right' | 'top-center' | 'split'
  imgSrc?: string
}

